const pick = (english, zh, en) => english ? en : zh;
const INCLUDE_RULE_COVERAGE = typeof GRAMMAR_RUNTIME === 'undefined' || !GRAMMAR_RUNTIME;

const labels = {
  subject: ['主语', 'Subject'], predicate: ['谓语动词', 'Predicate verb'], object: ['宾语', 'Object'],
  indirectObject: ['间接宾语', 'Indirect object'], directObject: ['直接宾语', 'Direct object'],
  objectComplement: ['宾语补足语', 'Object complement'], clause: ['从句', 'Clause'], conjunction: ['连接词', 'Linker'],
  reporting: ['报告语', 'Reporting clause'], quote: ['直接引语', 'Direct quotation'],
  reported: ['宾语从句（转述内容）', 'Object clause (reported content)'], auxiliary: ['助动词', 'Auxiliary'], modal: ['情态动词', 'Modal verb'],
  adverbial: ['状语', 'Adverbial'], marker: ['结构标记', 'Structure marker'], pronoun: ['代词成分', 'Pronoun element']
};

const part = (english, piece) => ({
  text: piece[0], role: piece[1],
  label: pick(english, piece[2] || (labels[piece[1]] || [piece[1], piece[1]])[0], piece[3] || (labels[piece[1]] || [piece[1], piece[1]])[1])
});
const structureNote = (english, zh, en) => ({ visible: true, mode: 'structure', title: pick(english, '例句说明', 'Example focus'), body: pick(english, zh, en), detail: '' });
const question = (english, q, index) => {
  const options = [{ key: 'A', text: pick(english, q[2], q[3]) }, { key: 'B', text: pick(english, q[4], q[5]) }];
  let answer = q[6];
  if (index % 2 === 1) {
    options.reverse();
    options.forEach((item, i) => { item.key = String.fromCharCode(65 + i); });
    answer = answer === 'A' ? 'B' : 'A';
  }
  return { question: pick(english, q[0], q[1]), options, answer, correct: pick(english, q[7], q[8]), wrong: pick(english, `再看规则：${q[7]}`, `Check the rule: ${q[8]}`) };
};
const A = (ruleZh, ruleEn, pieces, q, noteZh, noteEn) => ({ ruleZh, ruleEn, pieces, q, noteZh, noteEn });
const Q = (zh, en, aZh, aEn, bZh, bEn, answer, whyZh, whyEn) => [zh, en, aZh, aEn, bZh, bEn, answer, whyZh, whyEn];
const REPORTED_SPEECH_ESSENCE_NARRATION={
  id:'reported-speech:reported-speech-essence',version:'v3',
  text:`同学让你把米娅的话转告别人。你有两种说法：一种像复制聊天记录，保留她当时的原话；另一种用你现在的身份、时间和地点，把意思重新讲一遍。前者叫直接引语，后者叫间接引语。<#0.8#>
Mia said, "I will call you tomorrow."。<#0.7#>引号告诉读者，I、you、tomorrow 都站在米娅说话的现场来理解。假设第二天，原来的听话人转述这件事，可以说：<#0.4#>Mia said that she would call me the next day。<#0.8#>主干是 Mia said，that 后面装的是她说的内容。原话里的 I 指米娅，所以变成 she；you 指现在的转述者，所以变成 me；tomorrow 从新的时间点回看，变成 the next day。will 变成 would，也是在过去的报告点看原来的将来。
但转述不是看到 said 就把所有词自动换掉。如果当天就转述，tomorrow 可能仍然是 tomorrow；如果说的是客观事实，也不一定后移时态。每一处变化都要看人物和时间有没有真的换。<#0.8#>
再看 Leo refused to leave。这里没有假装逐字复述，而是用 refused 直接概括“拒绝离开”这个交际意思。间接转述可以保留意思和功能，不必虚构一段带引号的原话。
操作时先判断原话是在陈述、提问、命令还是请求；再选 that、if 或 whether、疑问词，或合适的报告动词；最后站到报告现场，逐个核对人称、时态、时间和地点是否需要调整。`,
  lengthText:'586 字 · 约 2 分钟'
};

function makeLesson(english, spec, index) {
  if (!spec.atoms || spec.atoms.length < 3) throw new Error(`Reported-speech lesson needs at least three atomic rules: ${spec.id}`);
  const result={
    id: spec.id, no: String(index + 1).padStart(2, '0'), level: spec.level,
    title: pick(english, spec.title[0], spec.title[1]), meta: pick(english, spec.meta[0], spec.meta[1]),
    examples: spec.atoms.map((atom) => atom.pieces.map((piece) => piece[0]).join(' ')),
    analyses: spec.atoms.map((atom) => atom.pieces.map((piece) => part(english, piece))),
    exampleNotes: spec.atoms.map((atom) => structureNote(english, atom.noteZh, atom.noteEn)),
    rules: spec.atoms.map((atom) => pick(english, atom.ruleZh, atom.ruleEn)),
    ruleCoverage: INCLUDE_RULE_COVERAGE ? spec.atoms.map((_, i) => ({ exampleIndexes: [i], questionIndexes: [i] })) : [],
    questions: spec.atoms.map((atom, atomIndex) => question(english, atom.q, atomIndex))
  };
  if(spec.id==='reported-speech-essence')result.narration=REPORTED_SPEECH_ESSENCE_NARRATION;
  return result;
}

